update public.courses set description='An introduction to effective listening, speaking, reading and writing in English for university study and professional communication.',reading_plan='{"overview":"Study English as a practical tool for understanding lectures, reading academic texts and expressing ideas clearly. Work through the modules in sequence, practise each skill weekly and revise your writing using feedback rather than memorising rules alone.","modules":[{"title":"Week 1-2: Communication and listening","topics":["Communication process and feedback","Verbal and non-verbal communication","Barriers to communication","Active listening and lecture notes"],"tasks":["Draw a communication model and label its main elements.","Listen to a short lecture and produce organised notes of its main points."]},{"title":"Week 3-4: Speech and pronunciation","topics":["English consonant and vowel sounds","Word stress","Sentence stress and intonation","Oral presentations"],"tasks":["Use a pronunciation dictionary to check the stress in ten academic words.","Deliver a two-minute presentation on a workplace issue and review its clarity."]},{"title":"Week 5-6: Reading and comprehension","topics":["Skimming and scanning","Intensive and extensive reading","Main ideas and supporting details","Inference and vocabulary in context"],"tasks":["Skim a newspaper article, then scan it for three specific facts.","Read an academic passage and answer literal and inferential questions."]},{"title":"Week 7-8: Grammar and sentence structure","topics":["Parts of speech and clauses","Subject-verb agreement","Tense consistency","Sentence fragments and run-on sentences","Punctuation"],"tasks":["Correct agreement, tense and punctuation errors in ten sentences.","Write simple, compound and complex sentences about university life."]},{"title":"Week 9-10: Paragraphs and academic writing","topics":["Topic sentences and paragraph unity","Cohesion and coherence","Essay planning and development","Summary and paraphrase","Acknowledging sources and avoiding plagiarism"],"tasks":["Plan and write a short essay on communication at work.","Summarise a passage in your own words and acknowledge its source.","Revise the essay for paragraph unity and logical connections."]},{"title":"Week 11-12: Functional writing and revision","topics":["Formal letters","Professional emails","Reports","Editing and proofreading"],"tasks":["Draft a formal letter requesting an industrial visit to a Nigerian organisation.","Write a short report on a student meeting with findings and recommendations.","Complete a timed revision exercise covering comprehension, grammar and writing."]}],"key_terms":[{"term":"Communication","definition":"The exchange of information and meaning through verbal or non-verbal messages."},{"term":"Feedback","definition":"A response that helps a sender judge how a message has been received and understood."},{"term":"Active listening","definition":"Attentive listening that involves interpreting, clarifying and responding to a message."},{"term":"Phoneme","definition":"The smallest distinctive sound unit that can distinguish meaning in a language."},{"term":"Skimming","definition":"Reading quickly to identify the general meaning or main ideas of a text."},{"term":"Scanning","definition":"Searching a text quickly for specific information."},{"term":"Concord","definition":"Grammatical agreement, especially between a subject and its verb."},{"term":"Coherence","definition":"The logical organisation and connection of ideas so that a text makes sense."},{"term":"Paraphrase","definition":"A restatement of an idea in substantially different wording and structure while retaining its meaning."},{"term":"Plagiarism","definition":"Presenting another person’s words or ideas as one’s own without appropriate acknowledgement."}],"exam_tips":["Read the passage before answering comprehension questions and support inferences with textual evidence.","Identify the head of the subject before choosing a verb in an agreement question.","For summaries, retain essential ideas, omit examples and observe the stated word limit.","Plan essays and formal letters before writing, using an appropriate tone and clear paragraphs.","Reserve time to check spelling, punctuation, tense consistency and whether every part of the task is answered."]}'::jsonb where slug='gst-111';
) v(p,q,a,b,c,k) where c.slug='gst-111';
update public.courses set description='An introduction to recording business transactions and preparing basic financial statements using double-entry principles.',reading_plan='{"overview":"This course develops the foundations of financial accounting for a simple business, from source documents to financial statements. Practise entries and calculations regularly, trace each transaction through the books, and check how it affects the accounting equation.","modules":[{"title":"Week 1-2: Accounting Foundations","topics":["Purpose and users of financial accounting","Assets, liabilities, equity, income and expenses","Accounting equation","Business entity, going concern and accrual concepts"],"tasks":["Classify ten business items as assets, liabilities, equity, income or expenses.","Show the accounting-equation effect of five simple transactions."]},{"title":"Week 3-4: Source Documents and Double Entry","topics":["Invoices, receipts and credit notes","Books of original entry","Debit and credit rules","Ledger accounts and balancing"],"tasks":["Match sample transactions to their source documents and books of original entry.","Post cash and credit transactions to ledger accounts."]},{"title":"Week 5-6: Cash Book and Trial Balance","topics":["Cash and bank columns","Cash discounts and trade discounts","Trial balance preparation","Errors and suspense accounts"],"tasks":["Prepare a simple cash book and extract a trial balance.","Identify errors that a balanced trial balance cannot reveal."]},{"title":"Week 7-8: Adjustments and Asset Measurement","topics":["Accrued and prepaid expenses","Depreciation and carrying amount","Irrecoverable debts and receivables allowance","Inventory valuation and cost of sales"],"tasks":["Calculate straight-line depreciation and prepare the entry.","Adjust expenses for accruals and prepayments and compute cost of sales."]},{"title":"Week 9-10: Financial Statements for a Sole Trader","topics":["Statement of profit or loss","Gross profit and net profit","Statement of financial position","Capital, drawings and closing equity"],"tasks":["Prepare basic financial statements from an adjusted trial balance.","Reconcile opening capital to closing capital using profit and drawings."]},{"title":"Week 11-12: Reconciliation, Control and Interpretation","topics":["Bank reconciliation","Receivables and payables control accounts","Internal controls over cash","Basic liquidity and profitability ratios"],"tasks":["Prepare a bank reconciliation after updating the cash book.","Calculate current ratio and gross profit margin and explain their limitations."]}],"key_terms":[{"term":"Asset","definition":"A present economic resource controlled by an entity as a result of past events."},{"term":"Liability","definition":"A present obligation to transfer an economic resource as a result of past events."},{"term":"Equity","definition":"The residual interest in assets after deducting liabilities."},{"term":"Double entry","definition":"The recording of each transaction with equal total debits and credits."},{"term":"Accrual basis","definition":"Recording transactions when their economic effects occur rather than only when cash moves."},{"term":"Trial balance","definition":"A list of ledger balances used to check whether total debits equal total credits."},{"term":"Depreciation","definition":"The systematic allocation of an asset’s depreciable amount over its useful life."},{"term":"Inventory","definition":"Assets held for sale, in production for sale, or as materials and supplies for production."},{"term":"Drawings","definition":"Cash or other assets withdrawn by a sole trader for personal use."},{"term":"Bank reconciliation","definition":"An explanation of differences between the cash book bank balance and the bank statement balance."}],"exam_tips":["State whether an account is an asset, liability, equity, income or expense before choosing debit or credit.","Show workings clearly and label naira amounts, especially for depreciation and cost of sales.","Remember that a balanced trial balance does not prove that every entry is correct.","Separate business expenses from drawings and capital expenditure.","For bank reconciliation, update the cash book for bank entries first and then reconcile timing differences."]}'::jsonb where slug='rsu-ehr-111';
) v(p,q,a,b,c,k) where c.slug='rsu-ehr-111';
update public.courses set description='An introduction to financial decisions, financial institutions, basic financial analysis and the management of funds in organisations.',reading_plan='{"overview":"This introductory plan covers the purpose of finance, financial markets and the basic tools used to make financing and investment decisions. Study the concepts before attempting short numerical exercises, and relate each topic to Nigerian households and businesses. Use your lecturer’s outline to confirm the emphasis for your examination.","modules":[{"title":"Week 1-2: Foundations of finance","topics":["Meaning and scope of finance","Personal, business and public finance","Investment, financing and dividend decisions","Financial objectives and stakeholder interests"],"tasks":["Read introductory notes and distinguish finance from accounting.","Classify six business decisions as investment, financing or dividend decisions."]},{"title":"Week 3-4: Financial system and institutions","topics":["Financial intermediation","Money and capital markets","Commercial banks and other financial institutions","Roles of the CBN, SEC and NGX"],"tasks":["Create a table comparing money and capital markets.","Explain how a Nigerian bank channels savings into loans."]},{"title":"Week 5-6: Financial statements and analysis","topics":["Statement of financial position","Statement of profit or loss","Cash flows versus accounting profit","Liquidity and profitability ratios"],"tasks":["Identify assets, liabilities and equity in a simple business case.","Calculate current ratio and net profit margin from sample figures."]},{"title":"Week 7-8: Time value of money and risk","topics":["Simple and compound interest","Present and future values","Risk and expected return","Diversification and inflation"],"tasks":["Calculate interest on a naira deposit using simple and compound methods.","Discount a single future cash flow and explain the result."]},{"title":"Week 9-10: Sources of finance and investment appraisal","topics":["Internal and external financing","Debt and equity finance","Payback period","Net present value and investment decisions"],"tasks":["Compare retained earnings, a bank loan and a share issue.","Calculate payback and NPV for a small investment project."]},{"title":"Week 11-12: Working capital and financial control","topics":["Cash, inventories and receivables","Trade credit and short-term obligations","Cash budgeting","Ethics and internal financial controls"],"tasks":["Prepare a three-month cash budget using opening cash and forecast receipts and payments.","Suggest controls for payroll payments and petty cash in an HR office."]}],"key_terms":[{"term":"Finance","definition":"The study and management of money, funding and investment decisions."},{"term":"Financial intermediation","definition":"The process through which institutions channel funds from savers to borrowers."},{"term":"Money market","definition":"The market for short-term debt instruments, generally with original maturities of one year or less."},{"term":"Capital market","definition":"The market for equity and longer-term debt securities."},{"term":"Working capital","definition":"Current assets minus current liabilities, also called net working capital."},{"term":"Liquidity","definition":"The ability to meet short-term obligations as they fall due."},{"term":"Equity","definition":"The residual ownership interest in assets after deducting liabilities."},{"term":"Time value of money","definition":"The principle that money available today is worth more than the same amount received later at a positive required return."},{"term":"Net present value","definition":"The present value of project cash inflows minus the present value of project cash outflows."},{"term":"Diversification","definition":"Spreading investments across assets to reduce exposure to asset-specific risk."}],"exam_tips":["Distinguish investment decisions from financing decisions and dividend decisions.","Write the formula, substitute figures and show units in every numerical answer.","Match interest rates to the time period and distinguish simple from compound interest.","Explain why profit and available cash can differ.","Practise interpreting ratios and NPV rather than merely calculating them."]}'::jsonb where slug='rsu-ehr-113';
) v(p,q,a,b,c,k) where c.slug='rsu-ehr-113';