insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which element completes the communication loop by showing the receiver’s response?','Encoding','Feedback','Channel','B'),
(2,'Which situation illustrates a physical barrier to communication?','Loud construction noise outside a lecture hall','An unfamiliar technical term','A listener’s prejudice','A'),
(3,'Which action best demonstrates active listening?','Planning a reply while ignoring the speaker','Interrupting after every sentence','Asking a relevant question to clarify a point','C'),
(4,'What is the main purpose of lecture notes?','To transcribe every spoken word without selection','To replace attendance at all future lectures','To record key ideas and useful supporting information','C'),
(5,'Which is an example of non-verbal communication?','Nodding to show agreement','Sending a written memo','Reading a notice aloud','A'),
(6,'What is a phoneme?','A complete written paragraph','A sound unit that can distinguish word meanings','A punctuation mark','B'),
(7,'Which pair differs in its initial consonant phoneme?','pat and bat','cat and cats','play and played','A'),
(8,'On which syllable is the main stress placed in the noun teacher?','Second','Both equally','First','C'),
(9,'What does intonation refer to?','The arrangement of letters in a word','The rise and fall of pitch in speech','The speed of handwriting','B'),
(10,'Which practice best improves an oral presentation?','Reading every slide without looking up','Organising points and rehearsing aloud','Using unexplained jargon throughout','B'),
(11,'Which reading technique gives a quick overview of a passage?','Scanning','Copying','Skimming','C'),
(12,'Which technique is best for locating an examination date in a timetable?','Scanning','Extensive reading','Paraphrasing','A'),
(13,'What is the main idea of a paragraph?','Its longest word','Its final punctuation mark','Its central point','C'),
(14,'What does making an inference involve?','Repeating only the title','Drawing a reasonable conclusion from clues in a text','Adding unsupported personal opinions','B'),
(15,'Which practice is an example of extensive reading?','Reading several novels for general understanding and enjoyment','Searching a list for one name','Analysing one sentence for its grammar','A'),
(16,'Choose the grammatically correct sentence.','The list of candidates is on the desk.','The list of candidates are on the desk.','The list of candidates were on the desk.','A'),
(17,'Choose the correct completion: Each of the workers ___ an identity card.','have','has','are having','B'),
(18,'Which sentence uses the past tense correctly?','She attends the meeting yesterday.','She will attend the meeting yesterday.','She attended the meeting yesterday.','C'),
(19,'Which option is a complete sentence?','Because the lecturer arrived.','The lecturer explained the topic.','During the morning lecture.','B'),
(20,'Which sentence correctly joins two independent clauses?','The lecture ended the students left.','The lecture ended, the students left.','The lecture ended, and the students left.','C'),
(21,'Which sentence uses an apostrophe to indicate possession by one student?','The student’s notebook is missing.','The students notebook is missing.','The students’ notebook is missing.','A'),
(22,'What is the usual function of a topic sentence?','To list all the references','To introduce an unrelated example','To state the main point of a paragraph','C'),
(23,'Which linking expression signals contrast?','However','Furthermore','Similarly','A'),
(24,'Which feature best demonstrates paragraph unity?','Every sentence introduces an unrelated topic','Every sentence supports one central idea','Every sentence has the same number of words','B'),
(25,'What should a good summary do?','Present essential ideas briefly without changing their meaning','Include every example from the original','Add new arguments unrelated to the original','A'),
(26,'Which practice is an acceptable paraphrase?','Changing two words and omitting the source','Restating an idea in new wording and structure with source acknowledgement','Copying a paragraph without quotation or citation','B'),
(27,'Which action constitutes plagiarism?','Citing a source used in your essay','Marking borrowed words as a quotation with a citation','Submitting another person’s essay as your own','C'),
(28,'Which closing conventionally matches Dear Sir in a formal letter?','Yours affectionately','Yours faithfully','Cheers','B'),
(29,'Which email subject line is most appropriate for a lecturer?','Hello!!!','Something important maybe','Request for clarification on GST 111 assignment','C'),
(30,'Which section of a report normally proposes actions based on findings?','Recommendations','Title page','List of abbreviations','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'What is a main purpose of financial accounting?','Guaranteeing that a business will earn a profit','Providing financial information for users’ decisions','Setting every market price in the economy','B'),
(2,'Which user is primarily interested in a business’s ability to repay a loan?','A lender','A leisure visitor','An unrelated sports club','A'),
(3,'Which equation is correct?','Assets = Liabilities − Equity','Equity = Assets + Liabilities','Assets = Liabilities + Equity','C'),
(4,'A business has assets of ₦900,000 and liabilities of ₦350,000. What is its equity?','₦1,250,000','₦550,000','₦350,000','B'),
(5,'Which concept requires the owner’s personal transactions to be distinguished from business transactions?','Going concern','Consistency','Business entity','C'),
(6,'Under accrual accounting, when is an expense generally recognised?','When it is incurred, whether or not it has been paid','Only when cash is withdrawn by the owner','Only at the date the business closes permanently','A'),
(7,'Which document normally supports a seller’s credit sale?','Sales invoice','Employee leave form','Bank deposit slip alone','A'),
(8,'What is the usual purpose of a seller’s credit note?','Demanding payment for a new credit sale','Recording the owner’s initial capital deposit','Reducing an amount owed by a customer, such as for accepted returns','C'),
(9,'Which book normally records credit sales of goods held for resale?','Purchases day book','Sales day book','Petty cash book','B'),
(10,'What is the entry when the owner introduces cash as capital?','Debit cash; credit capital','Debit capital; credit cash','Debit purchases; credit sales','A'),
(11,'Goods for resale are purchased on credit under a periodic inventory system. What is the entry?','Debit trade payables; credit purchases','Debit cash; credit capital','Debit purchases; credit trade payables','C'),
(12,'A customer pays an outstanding debt through the bank. What is the entry?','Debit trade receivables; credit bank','Debit bank; credit trade receivables','Debit sales; credit purchases','B'),
(13,'What is the normal balance of an expense account?','Credit','Debit','Always zero','B'),
(14,'What is a contra entry in a cash book with cash and bank columns?','A credit purchase from a supplier','A customer’s return of faulty goods','A transfer between the business’s cash and bank accounts','C'),
(15,'Goods have a list price of ₦50,000 with a 10% trade discount. What amount is recorded as purchases?','₦45,000','₦50,000','₦55,000','A'),
(16,'A supplier accepts ₦19,000 in full settlement of ₦20,000 owed. What is the cash discount received?','₦19,000','₦20,000','₦1,000','C'),
(17,'What does a trial balance primarily check?','Whether total ledger debits equal total ledger credits','Whether every transaction has been recorded correctly','Whether the business has sufficient cash for all future needs','A'),
(18,'Which error may leave a trial balance balanced?','Recording only the debit side of a transaction','Complete omission of a transaction','Adding a debit balance incorrectly without another error','B'),
(19,'When may a suspense account be used temporarily?','Whenever a customer pays an invoice in full','Whenever depreciation is correctly recorded','When a trial balance difference awaits investigation','C'),
(20,'Rent of ₦120,000 is paid, and ₦20,000 relates to the next period. What is the current-period rent expense?','₦140,000','₦100,000','₦120,000','B'),
(21,'What is the adjusting entry for unpaid electricity expense at year-end?','Debit electricity expense; credit accrued expenses','Debit accrued expenses; credit electricity expense','Debit drawings; credit capital','A'),
(22,'A machine costs ₦500,000, has residual value ₦50,000 and a five-year useful life. What is annual straight-line depreciation?','₦100,000','₦90,000','₦110,000','B'),
(23,'Equipment cost is ₦300,000 and accumulated depreciation is ₦80,000. What is its carrying amount?','₦220,000','₦380,000','₦80,000','A'),
(24,'What is the entry to write off an irrecoverable trade debt when no allowance was previously recognised?','Debit trade receivables; credit sales','Debit bank; credit trade receivables','Debit irrecoverable debt expense; credit trade receivables','C'),
(25,'How is inventory generally measured under IAS 2?','Always at selling price before selling costs','At the lower of cost and net realisable value','Always at the highest recent purchase price','B'),
(26,'Opening inventory is ₦40,000, net purchases ₦180,000 and closing inventory ₦30,000. What is cost of sales?','₦250,000','₦170,000','₦190,000','C'),
(27,'Sales are ₦300,000 and cost of sales is ₦190,000. What is gross profit?','₦110,000','₦490,000','₦190,000','A'),
(28,'Opening capital is ₦200,000, profit is ₦60,000 and drawings are ₦25,000. With no new capital, what is closing capital?','₦285,000','₦165,000','₦235,000','C'),
(29,'A cheque issued is recorded in the cash book but not yet presented to the bank. How is it treated?','As new sales revenue in the cash book','As a timing difference in the bank reconciliation','As an additional expense recorded a second time','B'),
(30,'Current assets are ₦240,000 and current liabilities are ₦120,000. What is the current ratio?','2:1','0.5:1','3:1','A')
insert into public.questions(course_id,position,question,option_a,option_b,option_c,correct_option) select c.id,v.p,v.q,v.a,v.b,v.c,v.k from public.courses c,(values
(1,'Which activity is primarily a financing decision?','Buying a delivery van','Raising funds through a bank loan','Choosing a new warehouse site','B'),
(2,'Which is the usual long-term financial objective of a shareholder-owned firm?','Maximise sustainable shareholder wealth','Maximise sales regardless of costs','Eliminate every business risk','A'),
(3,'Which activity is an investment decision?','Paying a dividend','Issuing ordinary shares','Purchasing production equipment','C'),
(4,'Financial intermediaries mainly connect which groups?','Taxpayers and customs officials','Savers and borrowers','Employees and trade unions','B'),
(5,'Which institution conducts monetary policy in Nigeria?','Nigerian Exchange Limited','Corporate Affairs Commission','Central Bank of Nigeria','C'),
(6,'Which instrument is normally traded in the money market?','A 91-day Treasury bill','An ordinary share','A 20-year corporate bond','A'),
(7,'Which transaction belongs to the capital market?','Buying a 30-day bill','Issuing ordinary shares','Taking a seven-day interbank loan','B'),
(8,'What is a principal role of Nigeria’s SEC?','Printing naira notes','Setting individual employees’ wages','Regulating the capital market','C'),
(9,'Which statement reports assets, liabilities and equity at a particular date?','Statement of financial position','Statement of cash flows','Statement of profit or loss','A'),
(10,'Which equation expresses the accounting identity?','Assets = Equity − Liabilities','Assets = Liabilities + Equity','Assets = Revenue + Expenses','B'),
(11,'A business has current assets of ₦600,000 and current liabilities of ₦300,000. What is its current ratio?','0.5:1','3:1','2:1','C'),
(12,'Net profit is ₦80,000 and sales are ₦400,000. What is the net profit margin?','20%','5%','50%','A'),
(13,'Why can a profitable business experience a cash shortage?','Profit always equals cash receipts','Depreciation requires an immediate cash payment','Customers may not yet have paid for credit sales','C'),
(14,'What is the simple interest on ₦100,000 at 10% per year for two years?','₦10,000','₦20,000','₦21,000','B'),
(15,'What is the value of ₦100,000 after two years at 10% interest compounded annually?','₦121,000','₦120,000','₦110,000','A'),
(16,'At a 10% annual discount rate, what is the present value of ₦110,000 received in one year?','₦121,000','₦110,000','₦100,000','C'),
(17,'What does investment risk mean in introductory finance?','Uncertainty about actual investment returns','A guarantee of financial loss','The total absence of price changes','A'),
(18,'Which risk is most directly reduced by holding a diversified portfolio?','Economy-wide recession risk','Firm-specific risk','General inflation risk','B'),
(19,'If nominal returns remain unchanged while inflation rises, what usually happens to real returns?','They must become zero','They rise','They fall','C'),
(20,'Which source of finance is generated internally?','A new bank loan','Retained earnings','A new share issue','B'),
(21,'Which statement correctly describes debt finance?','It normally creates contractual repayment obligations','It gives every lender ordinary voting shares','It never carries interest','A'),
(22,'An ordinary shareholder is primarily which type of provider of funds?','A secured short-term lender','A trade creditor','An owner providing equity capital','C'),
(23,'A project costs ₦120,000 and generates ₦40,000 annually. What is its simple payback period?','Two years','Three years','Four years','B'),
(24,'A project’s discounted inflows are ₦250,000 and discounted outflows are ₦200,000. What is its NPV?','₦50,000','−₦50,000','₦450,000','A'),
(25,'For an independent project with no capital rationing, which NPV supports acceptance?','An NPV below zero','An NPV equal to the initial cost only','An NPV above zero','C'),
(26,'Current assets are ₦900,000 and current liabilities are ₦550,000. What is net working capital?','₦350,000','₦1,450,000','₦550,000','A'),
(27,'Which item is normally a current asset?','A factory building','Accounts receivable due within 30 days','A ten-year loan payable','B'),
(28,'What does trade credit allow a buyer to do?','Receive goods now and pay the supplier later','Avoid recording a liability','Acquire goods without any payment obligation','A'),
(29,'Opening cash is ₦50,000, receipts are ₦200,000 and payments are ₦180,000. What is closing cash?','₦30,000','₦430,000','₦70,000','C'),
(30,'Which measure best strengthens payroll payment control?','Allowing one officer to create staff and approve payments','Separating payroll preparation from payment approval','Paying without checking employee records','B')
